<template><section><div class="page-heading"><div><h1>员工</h1><p>管理员工状态、所属部门和初始登录凭据。</p></div><el-button type="primary" :icon="Plus" @click="openCreate">创建员工</el-button></div><div class="filters"><el-input v-model="query" clearable placeholder="搜索员工邮箱" :prefix-icon="Search"/><el-select v-model="statusFilter" clearable placeholder="全部状态"><el-option label="在职" value="active"/><el-option label="停用" value="disabled"/><el-option label="已离职" value="terminated"/></el-select></div><el-table v-loading="loading" :data="filtered"><el-table-column prop="email" label="邮箱" min-width="230"/><el-table-column label="员工 ID" width="120"><template #default="{row}">{{ maskEmployeeId(row.id) }}</template></el-table-column><el-table-column label="部门" min-width="140"><template #default="{row}">{{ departmentName(row.department_id) }}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="statusType(row.status)">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="首次改密" width="110"><template #default="{row}">{{ row.must_change_password ? '待完成' : '已完成' }}</template></el-table-column><el-table-column label="操作" width="280" fixed="right"><template #default="{row}"><el-button text :icon="View" @click="router.push({name:'EnterpriseEmployeeDetail',params:{id:row.id}})">详情</el-button><el-button text :icon="Edit" :disabled="row.status==='terminated'" @click="openEdit(row)">编辑</el-button><el-button v-if="row.status==='active'" text type="warning" @click="setStatus(row,'disabled')">停用</el-button><el-button v-else-if="row.status==='disabled'" text type="success" @click="setStatus(row,'active')">恢复</el-button><el-button text type="danger" :disabled="row.status==='terminated'" @click="terminate(row)">离职</el-button></template></el-table-column></el-table><el-alert v-if="loadError" type="error" :title="loadError" :closable="false" class="load-error"><el-button size="small" @click="load">重试</el-button></el-alert><el-empty v-else-if="!loading&&!filtered.length" description="暂无匹配员工"/>
<el-dialog v-model="createVisible" title="创建员工" width="min(92vw, 500px)" @closed="resetCreate"><el-alert title="初始密码仅用于本次提交，创建成功后不会显示或保存。" type="warning" :closable="false" class="notice"/><el-form ref="createFormRef" :model="createForm" :rules="createRules" label-position="top"><el-form-item label="邮箱" prop="email"><el-input v-model="createForm.email" autocomplete="off"/></el-form-item><el-form-item label="初始密码" prop="initial_password"><el-input v-model="createForm.initial_password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="部门"><el-select v-model="createForm.department_id" clearable placeholder="不分配部门"><el-option v-for="department in departments" :key="department.id" :label="department.name" :value="department.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="createEmployee">创建</el-button></template></el-dialog>
<el-dialog v-model="editVisible" title="编辑员工" width="min(92vw, 500px)"><el-form label-position="top"><el-form-item label="邮箱"><el-input :model-value="editing?.email" disabled/></el-form-item><el-form-item label="部门"><el-select v-model="editDepartment" clearable placeholder="不分配部门"><el-option v-for="department in departments" :key="department.id" :label="department.name" :value="department.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="editVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveEmployee">保存</el-button></template></el-dialog></section></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{useRouter}from'vue-router';import type{FormInstance,FormRules,TagProps}from'element-plus';import{ElMessage,ElMessageBox}from'element-plus';import{Edit,Plus,Search,View}from'@element-plus/icons-vue';import{enterpriseAPI,isEnterpriseEmployeeDepartmentInvalid,isEnterpriseEmployeeVersionConflict}from'@/api/enterprise';import{validatePassword}from'@/features/enterprise/validation';import type{EnterpriseDepartment,EnterpriseEmployee}from'@/types/enterprise';const router=useRouter();const employees=ref<EnterpriseEmployee[]>([]),departments=ref<EnterpriseDepartment[]>([]),loading=ref(false),loadError=ref(''),saving=ref(false),query=ref(''),statusFilter=ref(''),createVisible=ref(false),editVisible=ref(false),createFormRef=ref<FormInstance>(),editing=ref<EnterpriseEmployee>(),editDepartment=ref<number|null>(null);const maskEmployeeId=(_id:number)=>'••••••••••';const createForm=reactive({email:'',initial_password:'',department_id:null as number|null});const createRules:FormRules={email:[{required:true,type:'email',message:'请输入有效邮箱',trigger:'blur'}],initial_password:[{validator:(_r,_v,cb)=>{const m=validatePassword(createForm.initial_password);m?cb(new Error(m)):cb()},trigger:'blur'}]};const filtered=computed(()=>employees.value.filter(e=>(!query.value||e.email.toLowerCase().includes(query.value.toLowerCase()))&&(!statusFilter.value||e.status===statusFilter.value)));const departmentName=(id?:number|null)=>departments.value.find(d=>d.id===id)?.name||'未分配';const statusLabel=(s:string)=>({active:'在职',disabled:'停用',terminated:'已离职'}[s]||s);const statusType=(s:string):TagProps['type']=>s==='active'?'success':s==='disabled'?'warning':'info';async function load(){loading.value=true;loadError.value='';try{[employees.value,departments.value]=await Promise.all([enterpriseAPI.listEmployees({suppressUnavailableRedirect:true}),enterpriseAPI.listDepartments({suppressUnavailableRedirect:true})])}catch(error){loadError.value=(error as{message?:string})?.message||'员工列表加载失败'}finally{loading.value=false}}function openCreate(){resetCreate();createVisible.value=true}function resetCreate(){createForm.email='';createForm.initial_password='';createForm.department_id=null;createFormRef.value?.clearValidate()}async function createEmployee(){if(!await createFormRef.value?.validate().catch(()=>false))return;saving.value=true;try{await enterpriseAPI.createEmployee({...createForm});createVisible.value=false;resetCreate();ElMessage.success('员工已创建');await load()}finally{saving.value=false}}function openEdit(row:EnterpriseEmployee){editing.value=row;editDepartment.value=row.department_id??null;editVisible.value=true}async function handleEmployeeVersionConflict(error:unknown){if(!isEnterpriseEmployeeVersionConflict(error))throw error;ElMessage.warning('该员工已被其他管理员修改，已刷新为最新数据，请重新操作。');await load()}async function saveEmployee(){if(!editing.value)return;const target=editing.value;saving.value=true;try{await enterpriseAPI.updateEmployee(target.id,{status:target.status==='disabled'?'disabled':'active',department_id:editDepartment.value,version:target.version});editVisible.value=false;ElMessage.success('员工信息已更新');await load()}catch(error){if(isEnterpriseEmployeeVersionConflict(error)){await handleEmployeeVersionConflict(error);const latest=employees.value.find(e=>e.id===target.id);if(latest){editing.value=latest;editDepartment.value=latest.department_id??null}}else if(isEnterpriseEmployeeDepartmentInvalid(error)){ElMessage.error('所选部门无效，请重新选择部门后重试')}else{editVisible.value=false;ElMessage.error((error as{message?:string})?.message||'员工信息更新失败')}}finally{saving.value=false}}async function setStatus(row:EnterpriseEmployee,status:'active'|'disabled'){try{await enterpriseAPI.updateEmployee(row.id,{status,department_id:row.department_id??null,version:row.version});ElMessage.success(status==='active'?'员工已恢复':'员工已停用');await load()}catch(error){await handleEmployeeVersionConflict(error)}}async function terminate(row:EnterpriseEmployee){await ElMessageBox.confirm(`确认将 ${row.email} 标记为离职？该操作会撤销其会话。`,'员工离职',{type:'warning'});await enterpriseAPI.terminateEmployee(row.id);ElMessage.success('员工已离职');await load()}onMounted(load);</script>
<style scoped>.page-heading{display:flex;justify-content:space-between;gap:20px;margin-bottom:20px}.page-heading h1{margin:0 0 6px;font-size:26px}.page-heading p{margin:0;color:#64748b}.filters{display:flex;gap:12px;margin-bottom:18px}.filters .el-input{max-width:340px}.filters .el-select{width:160px}.notice{margin-bottom:18px}.load-error{margin-top:12px}@media(max-width:640px){.page-heading,.filters{flex-direction:column}.page-heading .el-button,.filters .el-input,.filters .el-select{width:100%;max-width:none}}</style>
